#include <iostream>
#include <cstdlib>
using namespace std;

int main() {
  int n;
  if (!(cin >> n)) {
    cerr << "Error: invalid input." << endl;
    return EXIT_FAILURE;
  }
  if (n <= 1 || (n % 2 == 0)) {
    cout << "Error: n must be an odd integer greater than 1." << endl;
    return EXIT_FAILURE;
  }
  int mid = n / 2; // zero-based middle row index
  // top half including middle
  for (int r = 0; r <= mid; ++r) {
    int stars = n - 2*r;           // number of stars on this row (contiguous or two with spaces)
    if (stars == n) {
      // first row: all stars
      for (int k = 0; k < n; ++k) cout << '*';
    } else if (stars == 1) {
      // middle row: single star
      cout << '*';
    } else {
      // two stars with spaces between
      cout << '*';
      for (int k = 0; k < stars - 2; ++k) cout << ' ';
      cout << '*';
    }
    cout << '\n';
  }
  // bottom half (mirror of top half excluding middle)
  for (int r = mid - 1; r >= 0; --r) {
    int stars = n - 2*r;
    if (stars == n) {
      for (int k = 0; k < n; ++k) cout << '*';
    } else if (stars == 1) {
      cout << '*';
    } else {
      cout << '*';
      for (int k = 0; k < stars - 2; ++k) cout << ' ';
      cout << '*';
    }
    cout << '\n';
  }
  return EXIT_SUCCESS;
}

