#include <iostream.h>
#include <stdlib.h>
class Complex {
private:
  double real;
  double imaginary;
public:
  // Single constructor acting as default and two-arg constructor
  Complex(double real = 0.0, double imaginary = 0.0)
    : real(real), imaginary(imaginary) {}
  double get_real(void);
  double get_imaginary(void);
  void set_real(double);
  void set_imaginary(double);
};

// ps1_6.C
#include "ps1_6.h"

double Complex::get_real(void) { return real; }

double Complex::get_imaginary(void) { return imaginary; }

void Complex::set_real(double r) { real = r; }

void Complex::set_imaginary(double i) { imaginary = i; }

int main()
{
  Complex c1;
  cout << "\n\n c1 = " << c1.get_real()
       << " + " << c1.get_imaginary() << "i " << endl ;
  Complex c2(7.25,-8.5);
  cout << "\n\n c2 = " << c2.get_real()
       << " + " << c2.get_imaginary() << "i " << endl ;
  c1.set_real(1.7);
  c1.set_imaginary(-6.7);
  cout << "\n\n c1 = " << c1.get_real()
       << " + " << c1.get_imaginary() << "i " << endl << endl;
  return EXIT_SUCCESS ;
}
